func newKeySet() unsafe.Pointer { return unsafe.Pointer(new(supportaccess.KeySet)) }

func newNKeySet(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]supportaccess.KeySet, n)))
}

func ptrKeySet(p unsafe.Pointer, c int32) any {
	r := (*supportaccess.KeySet)(p)
	switch c {
	case 0:
		return &r.ID
	case 1:
		return &r.InstanceID
	case 2:
		return &r.StaffDomain
	case 3:
		return &r.Keys
	case 4:
		return &r.ReceivedAt
	}
	return nil
}

func valueKeySet(p unsafe.Pointer, c int32) any {
	r := (*supportaccess.KeySet)(p)
	switch c {
	case 0:
		return r.ID
	case 1:
		if r.InstanceID == "" {
			return nil
		}
		return r.InstanceID
	case 2:
		return r.StaffDomain
	case 3:
		if r.Keys == nil {
			return keel.EmptyJSONArray
		}
		return r.Keys
	case 4:
		return r.ReceivedAt
	}
	return nil
}

